head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gDate;
scwin.gProcDepCd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vScrenID = 'ULDSTF10400.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//조건에 따른 버튼 생성여부 체크
scwin.fn_showOptButton = function() {
    // 시장구분이가  유가이면 보여준다.
    if (scwin.gLdMktTp == "1") {
        $c.stf.showObj(panel_ReserveTp, true);
    } else {
        $c.stf.showObj(panel_ReserveTp, false);
    }
};



// 특정 컬럼 숨기기
scwin.fn_Hidden_Col = function() {
    if (scwin.gLdMktTp == 1) {
        // 유가일때
        $c.cm.setColumnProp(grd_Grid, "REDISCLS_YN_NM", "Show", false); // 재공시여부 를  hidden

    }
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
        $c.stf.showObj(panel_2, true);
    } else {
        $c.stf.showObj(panel_2, false);
    }
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_emp.Reset();

    // 공시유보유형 리스트  셋팅
    dts_ReservTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=RESERV_TP_CD";
    dts_ReservTp.Reset();
};


// 화면 로딩시 디폴트 검색
scwin.fn_InitSearch = function() {
    //fn_Search();


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시유보현황--;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }

    //

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
        scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
        scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체	
        scwin.gEmpNo = "";
    }
    fn_Search();
} < !공시유보현황--;
클릭-- > function() {
    /******************************************************************
    2009.09.01 채권공시관련 - 채권상장팀이면 시장구분 : 4
    ******************************************************************/
    if (js_bond_yn == "Y") {
        scwin.gLdMktTp = "4";
    }

    /* 2009.09.01 채권공시하면서 수정함. ****************************************************
        상장폐지법인 제외 콤보가 0, 1을 자바로 넘기는데 자바에서는 Y,N 을 체크해서 수정함.
    ***************************************************************************************/
    var listStatCdTemp;
    if (scwin.getChkValue(chb_ListStatCd) == "0") {
        listStatCdTemp = "N";
    } else {
        listStatCdTemp = "Y";
    }
    /**************************************************************************************/

    var url = "/DisclosureStatus.do?method=listDisclosureReserve&inputMessageId=DSCLRESERVECOND_IN" + "&outputMessageId=DSCLRESERVELIST_OUT" + "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&RESERV_TP=" + $c.stf.getObjectValue(cmb_ReservTp) + "&LD_MKT_TP=" + scwin.gLdMktTp + "&LIST_STAT=" + listStatCdTemp + "&UP_DEP_CD=" + js_belngdepcd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_ReserveList.DataID = encodeURI(url);
    dts_ReserveList.reset();
    $c.cm.ShowWin(grd_Grid);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_ReserveList.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_ReserveList.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_ReserveList.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_ReserveList.getCellData(eval(obj), "ISUR_CD");
    scwin.gProcDepCd = dts_ReserveList.getCellData(eval(obj), "DEP_CD");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.dts_ReserveList_OnLoadError = function() {
    $c.stf.alert_error(dts_ReserveList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_ReserveList_OnLoadCompleted = function(rowcount) {
    if (dts_ReserveList.errorMsg) {
        $c.win.alert(dts_ReserveList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "공시유보현황 목록", "", "2");
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EmpList, js_emp_no) ;	

};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
    } else if (colid == "RESERV_RSN_NM") {
        // 로그인유저와 공시문서의 부서가 같으면 수정가능	& 당번일때		
        if (scwin.gProcDepCd == js_dep_cd ||
            js_duty == 'Y' || js_duty_chrg == 'Y') {
            // 유보사유 및 유보유형 수정화면		
            var url = "/dsclproc/ULDSTF10402.gfm";
            var winTitle = "유보처리현황";
            //frame.CreateDialogFrame("reserveMod", url , winTitle ,100, 100, 900, 490+30, "window" );		
            await $c.frame.CreateFrame("reserveStat", url, winTitle, 100, 100, 900, 490 + 30, "window", 0, 0, true);
        } else {
            // 유보사유 및 유보유형		
            var url = "/dsclproc/ULDSTF10401.gfm";
            var winTitle = "유보처리현황";
            await $c.frame.CreateDialogFrame("reserveStat", url, winTitle, 100, 100, 900, 460 + 30, "window");
        }
    } else if (colid == "ACPT_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 채권종목만...
    ******************************************************************/
    if (js_bond_yn == "Y") {
        $c.cm.IsurcdSearchBond(txb_isur_cd, txb_com_abbrv);
    } else {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    }
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_SetCode();
    scwin.fn_showOptButton();
    scwin.fn_Hidden_Col();
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_InitSearch();
};
